+++ b/docs/guides/assets/guide.css
@@ -0,0 +1,70 @@
+/* Guide stylesheet (STY-1..4). Docket tokens are imported unedited; this file only adds components. */
+@import url("tokens.css");
+
+@font-face { font-family: "Atkinson Hyperlegible Next"; font-weight: 400; src: url("fonts/next-400.woff2") format("woff2"); }
+@font-face { font-family: "Atkinson Hyperlegible Next"; font-weight: 600; src: url("fonts/next-600.woff2") format("woff2"); }
+@font-face { font-family: "Atkinson Hyperlegible Next"; font-weight: 700; src: url("fonts/next-700.woff2") format("woff2"); }
+@font-face { font-family: "Atkinson Hyperlegible Mono"; font-weight: 400; src: url("fonts/mono-400.woff2") format("woff2"); }
+@font-face { font-family: "Atkinson Hyperlegible Mono"; font-weight: 700; src: url("fonts/mono-700.woff2") format("woff2"); }
+
+/* STY-2: light theme, A4 portrait. The running header and page numbers (STY-4) come from print.mjs. */
+@page { size: A4 portrait; margin: 22mm 16mm 18mm; }
+:root { color-scheme: light; }
+body { margin: 0; font: var(--text-14)/1.5 var(--font-sans); color: var(--color-text-primary); background: var(--color-background); }
+h1 { font-size: var(--text-32); margin: 0 0 var(--space-3); }
+h2 { font-size: var(--text-24); margin: var(--space-6) 0 var(--space-2); border-bottom: 2px solid var(--color-primary); padding-bottom: var(--space-1); break-after: avoid; }
+h3 { font-size: var(--text-18); margin: var(--space-5) 0 var(--space-2); break-after: avoid; }
+a { color: var(--color-primary); }
+code, pre, kbd { font-family: var(--font-mono); font-size: var(--text-12); }
+code { background: var(--color-surface); padding: 0 var(--space-1); }
+
+/* Never split a step, figure, check row or code extract (STY-2). */
+.step, figure, .extract, .callout, tr, .cover, .front li { break-inside: avoid; }
+
+/* LRN-1 cover and front sheet */
+.cover { min-height: 230mm; display: flex; flex-direction: column; justify-content: center; border-left: 8px solid var(--color-primary); padding-left: var(--space-6); break-after: page; }
+.cover p { color: var(--color-text-secondary); font-size: var(--text-18); }
+.front { break-after: page; }
+.front ol { padding-left: var(--space-5); }
+.front li { margin-bottom: var(--space-3); }
+.front li strong { color: var(--color-primary); }
+
+/* LRN-2 three layers */
+.headline { font-size: var(--text-18); font-weight: 600; margin: 0 0 var(--space-2); }
+.summary { color: var(--color-text-secondary); margin: 0 0 var(--space-3); }
+details.depth { margin: var(--space-3) 0; }
+details.depth > summary { font-weight: 600; color: var(--color-primary); }
+
+/* LRN-5 numbered steps */
+ol.steps { list-style: none; counter-reset: step; padding: 0; }
+.step { counter-increment: step; position: relative; margin: 0 0 var(--space-3); padding: var(--space-2) var(--space-3) var(--space-2) 2.75rem; border: 1px solid var(--color-border); border-radius: var(--radius); }
+.step::before { content: counter(step); position: absolute; left: var(--space-3); top: var(--space-2); width: 1.5rem; height: 1.5rem; border-radius: 50%; background: var(--color-primary); color: #fff; font-weight: 700; text-align: center; line-height: 1.5rem; }
+.step .see { margin-top: var(--space-2); }
+.step .see::before { content: "You should see: "; font-weight: 600; color: var(--color-success); }
+
+/* Code, commands and captured output */
+pre { background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--radius); padding: var(--space-2) var(--space-3); margin: var(--space-2) 0; white-space: pre-wrap; overflow-wrap: anywhere; }
+pre.output { border-left: 4px solid var(--color-success); }
+.extract { margin: var(--space-3) 0; }
+.extract .ref { font-family: var(--font-mono); font-size: var(--text-12); }
+
+/* STY-3 rule chips and status colours */
+.chip { display: inline-block; font: 700 var(--text-12)/1.4 var(--font-mono); padding: 0 var(--space-2); border-radius: var(--radius); background: var(--color-accent); color: var(--color-primary); border: 1px solid var(--color-primary); }
+.callout { border-left: 4px solid var(--color-primary); background: var(--color-surface); padding: var(--space-2) var(--space-3); margin: var(--space-3) 0; }
+.callout.warn { border-color: var(--color-warn); }
+.callout.error { border-color: var(--color-error); }
+.callout.ok { border-color: var(--color-success); }
+.callout .label { font-weight: 700; display: block; }
+
+/* LRN-7, LRN-8, LRN-11 tables */
+table { border-collapse: collapse; width: 100%; margin: var(--space-3) 0; }
+th, td { border: 1px solid var(--color-border); padding: var(--space-1) var(--space-2); text-align: left; vertical-align: top; }
+th { background: var(--color-accent); }
+table.check th:first-child, table.check td:first-child { width: 40%; }
+
+/* LRN-4 diagrams, LRN-6 screenshots with numbered markers */
+figure { margin: var(--space-4) 0; }
+figure svg, figure img { max-width: 100%; height: auto; }
+figcaption { color: var(--color-text-secondary); font-size: var(--text-12); }
+.shot { position: relative; display: inline-block; }
+.marker { position: absolute; width: 1.4rem; height: 1.4rem; border-radius: 50%; background: var(--color-error); color: #fff; font-weight: 700; text-align: center; line-height: 1.4rem; transform: translate(-50%, -50%); }
